mapper.select:
SELECT t.ISSUANCE_ID, t.ISSUANCE_NO, t.PLAN_ID, t.BOND_NAME, t.BOND_CODE, t.BOND_TYPE, t.ISSUANCE_AMOUNT, t.CURRENCY_CODE, t.FACE_VALUE, t.COUPON_RATE, t.BOND_TERM, t.TERM_UNIT, t.PAYMENT_FREQUENCY, t.UNDERWRITER, t.TRUSTEE, t.RATING_AGENCY, t.CREDIT_RATING, t.LISTING_EXCHANGE, t.ISSUANCE_STATUS, t.ISSUANCE_DATE, t.MATURITY_DATE, t.INTEREST_PAYMENT_DATE, t.REDEMPTION_DATE, t.ACTUAL_ISSUANCE_AMOUNT, t.ISSUE_COST, t.UNDERWRITING_FEE, t.COMPANY_ID, t.COMPANY_NAME, t.CREATED_BY, t.CREATED_TIME, t.UPDATED_BY, t.UPDATED_TIME, t.REMARK, D1.ITEM_NAME AS BOND_TYPE_NAME, D2.ITEM_NAME AS CURRENCY_NAME, D3.ITEM_NAME AS TERM_UNIT_NAME, D4.ITEM_NAME AS PAYMENT_FREQUENCY_NAME, D5.ITEM_NAME AS CREDIT_RATING_NAME, D6.ITEM_NAME AS ISSUANCE_STATUS_NAME FROM TBL_BOND_ISSUANCE t LEFT JOIN TC_DICT_ITEM D1 ON t.BOND_TYPE = D1.ITEM_CODE AND D1.DICT_CODE = 'BOND_TYPE' LEFT JOIN TC_DICT_ITEM D2 ON t.CURRENCY_CODE = D2.ITEM_CODE AND D2.DICT_CODE = 'CURRENCY_TYPE' LEFT JOIN TC_DICT_ITEM D3 ON t.TERM_UNIT = D3.ITEM_CODE AND D3.DICT_CODE = 'TERM_UNIT' LEFT JOIN TC_DICT_ITEM D4 ON t.PAYMENT_FREQUENCY = D4.ITEM_CODE AND D4.DICT_CODE = 'PAYMENT_FREQUENCY' LEFT JOIN TC_DICT_ITEM D5 ON t.CREDIT_RATING = D5.ITEM_CODE AND D5.DICT_CODE = 'CREDIT_RATING' LEFT JOIN TC_DICT_ITEM D6 ON t.ISSUANCE_STATUS = D6.ITEM_CODE AND D6.DICT_CODE = 'ISSUANCE_STATUS' WHERE t.DELETE_FLAG = 0
AND t.ISSUANCE_ID = #{issuanceId}
AND t.PLAN_ID = #{planId}
AND t.BOND_NAME LIKE '%' || #{bondName} || '%'
AND t.BOND_CODE = #{bondCode}
AND t.BOND_TYPE = #{bondType}
AND t.CREDIT_RATING = #{creditRating}
AND t.ISSUANCE_STATUS = #{issuanceStatus}
AND t.COMPANY_ID = #{companyId}
AND t.ISSUANCE_DATE >= #{issuanceDateStart}
AND t.ISSUANCE_DATE <= #{issuanceDateEnd}
AND t.MATURITY_DATE >= #{maturityDateStart}
AND t.MATURITY_DATE <= #{maturityDateEnd}
ORDER BY t.${orderBy} ${orderDirection}
ORDER BY t.CREATED_TIME DESC
